  const existing = await getBooking(id);

  const roomId = input.roomId ?? existing.roomId;
  const startsAt = input.startsAt ? parseInstant(input.startsAt) : existing.startsAt;
  const endsAt = input.endsAt ? parseInstant(input.endsAt) : existing.endsAt;

  const hasTimeOrRoomChange =
